const response = $input.first().json;
const incoming = $('Counter Webhook').first().json;

// Decode base64 content from GitHub API
const scriptContent = Buffer.from(response.content, 'base64').toString('utf-8');

// Parse current BAGS value
const match = scriptContent.match(/const BAGS = (\d+)/);
const oldBags = match ? parseInt(match[1]) : 0;
const addBags = parseInt(incoming.bags) || 1;
const newBags = oldBags + addBags;

// Replace in content
const newContent = scriptContent.replace(/const BAGS = \d+/, `const BAGS = ${newBags}`);

// Encode back to base64
const newContentB64 = Buffer.from(newContent).toString('base64');

return [{
  json: {
    oldBags,
    addBags,
    newBags,
    newContentB64,
    sha: response.sha,
    donated: newBags * 100,
    addedDonation: addBags * 100
  }
}];

