const data = $input.first().json;
const prev = $('Compute New Counter').first().json;

// Check if donation reminder is due (multiples of 10 bags)
const shouldRemind = Math.floor(prev.newBags / 10) > Math.floor(prev.oldBags / 10);

return [{
  json: {
    success: true,
    newBags: prev.newBags,
    donated: prev.donated,
    message: `Counter updated: ${prev.oldBags} -> ${prev.newBags} (+${prev.addBags})`,
    donationReminder: shouldRemind 
      ? `POSLI ${prev.donated} Kc na Koridor.ua!` 
      : null
  }
}];
